sys_variable_value.value:
(function execute(inputs, outputs) {
    var tr = inputs.trigger_record;
    var fitScore = parseInt(tr.fit_score.toString(), 10);
    var threshold = parseInt(gs.getProperty('x_snc_aegis.screening.shortlist_threshold', '60'), 10);
    var appSysId = tr.application.toString();

    var newStage = fitScore >= threshold ? 'SHORTLISTED' : 'RECRUITER_REVIEW';

    // Update the Application stage
    var app = new GlideRecord('x_snc_aegis_application');
    if (app.get(appSysId)) {
        app.setValue('stage', newStage);
        app.update();
    }

    // Log
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Workflow',
        'STAGE_TRANSITION',
        appSysId,
        tr.requisition.toString(),
        'Fit Score: ' + fitScore + ' | Threshold: ' + threshold,
        'Application routed to: ' + newStage,
        fitScore / 100,
        '4/5ths rule threshold gate; Scores >= ' + threshold + ' auto-shortlisted'
    );

    outputs.new_stage = newStage;
    outputs.fit_score = fitScore;

})(inputs, outputs);

